import type { TopicText } from '../types';
const table: Record<string, TopicText> = {"t00":{"title":"ড্রাইভিং লাইসেন্স ও এর শ্রেণি","blocks":[{"text":"প্রাইভেট: বয়স 18 বছর বা তার বেশি (17 বছর বয়স থেকে সর্বোচ্চ এক বছরের জন্য অস্থায়ী অনুমতিপত্র), ড্রাইভিং স্কুলে প্রশিক্ষণ শেষ করা, তত্ত্বীয় ও ব্যবহারিক পরীক্ষায় পাস করা, ফি দেওয়া, এবং আগের লঙ্ঘনের জরিমানা পরিশোধ করা।"},{"text":"প্রাইভেট লাইসেন্স সর্বোচ্চ 10 বছর পর্যন্ত বৈধ থাকে। এটি দিয়ে চালকসহ সর্বোচ্চ 9 জন বহন করা যায় এবং 3500 কেজির বেশি ওজন নয় এমন ছোট গাড়ি চালানো যায়।"},{"text":"পাবলিক: বয়স 20 বছর বা তার বেশি, মেয়াদ 5 বছর। শ্রেণি 1: ট্যাক্সি (8 জন যাত্রী পর্যন্ত); শ্রেণি 2: হালকা পরিবহন (3500 কেজি পর্যন্ত) বা ভারী পরিবহন (এর বেশি); শ্রেণি 3: বাস (ছোট: 15 জন বা তার কম যাত্রী; বড়: এর বেশি)।"},{"text":"নির্মাণকাজের (ভারী যন্ত্রপাতির) যানবাহন: বয়স 20 বছর, মেয়াদ 5 বছর। মোটরসাইকেল: বয়স 18 বছর, মেয়াদ 10 বছর।"},{"text":"অ-সৌদিদের জন্য শর্ত: বৈধ ইকামা (আইনসম্মত বসবাসের অনুমতি) থাকা, গাড়ি চালাতে বাধা দেয় এমন রোগ ও অক্ষমতা থেকে মুক্ত থাকা, এবং নির্দিষ্ট কিছু অপরাধে (হামলা বা মাদক) কোনো আদালতের রায় না থাকা, যদি না তাদের রেকর্ড আনুষ্ঠানিকভাবে পরিষ্কার করা হয়ে থাকে।"},{"text":"লাইসেন্সে থাকে: নাম, আইডি নম্বর, জন্ম তারিখ, বিধিনিষেধ, ধরন, রক্তের গ্রুপ, ইস্যু ও মেয়াদ শেষের তারিখ, এবং জাতীয়তা।"}]},"t01":{"title":"গতি ও থামার দূরত্ব","blocks":[{"text":"সবসময় পরিস্থিতি অনুযায়ী গতি ঠিক রাখুন, যাতে সময়মতো থামতে পারেন। গতি, এবং তা পরিস্থিতি অনুযায়ী ঠিক না রাখা, সড়ক দুর্ঘটনার একটি প্রধান কারণ।"},{"text":"থামার দূরত্ব = প্রতিক্রিয়ার দূরত্ব + ব্রেক করার দূরত্ব। সাধারণত প্রতিক্রিয়ার সময় এক সেকেন্ড।"},{"text":"প্রতিক্রিয়া = (গতি ÷ 10) × 3 · ব্রেক = (গতি ÷ 10) × (গতি ÷ 10), শুকনো রাস্তায়।"},{"table":[["গতি","প্রতিক্রিয়ার দূরত্ব","ব্রেক করার দূরত্ব","থামার দূরত্ব"],["30 কিমি/ঘণ্টা","9 মিটার","9 মিটার","18 মিটার"],["50 কিমি/ঘণ্টা","15 মিটার","25 মিটার","40 মিটার"],["60 কিমি/ঘণ্টা","18 মিটার","36 মিটার","54 মিটার"],["80 কিমি/ঘণ্টা","24 মিটার","64 মিটার","88 মিটার"],["100 কিমি/ঘণ্টা","30 মিটার","100 মিটার","130 মিটার"],["120 কিমি/ঘণ্টা","36 মিটার","144 মিটার","180 মিটার"]]},{"text":"বেশি গতি, অমনোযোগ ও ক্লান্তি, এবং মাদক, মদ বা ঘুম আনে এমন ওষুধে প্রতিক্রিয়ার দূরত্ব বেড়ে যায়।"},{"text":"গতি, ভারী বোঝা, রাস্তার খারাপ অবস্থা (বালু, ভেজা রাস্তা), এবং খারাপ টায়ার বা ব্রেকে ব্রেক করার দূরত্ব বেড়ে যায়।"},{"text":"এটি কমাতে: গতি কমান, মনোযোগ বাড়ান, এবং চাপ না দিয়ে ব্রেকের ওপর পা রাখুন।"},{"text":"আপনার গতি মাত্র 10 কিমি/ঘণ্টা বেশি হলে (50 থেকে 60), থামার বদলে আপনি প্রায় 40 কিমি/ঘণ্টা গতিতে ধাক্কা খেতে পারেন, আর এর আঘাত সিট বেল্ট ছাড়া 6.5 মিটার উঁচু থেকে পড়ে যাওয়ার মতো।"}]},"t02":{"title":"সড়ক দুর্ঘটনা","blocks":[{"text":"দুর্ঘটনা বেশি হওয়ার কারণ: অতিরিক্ত গতি, নিয়ম না মানা, মোবাইল ফোন ব্যবহার ও সিট বেল্ট না বাঁধা, হঠাৎ লেন পরিবর্তন, এবং গাড়ি ও রাস্তার অবস্থা।"},{"text":"ছোট দুর্ঘটনা: ক্ষতি 5,000 রিয়ালের বেশি নয়, অথবা এমন আঘাত যাতে হাসপাতালে যেতে হয় না। বড় দুর্ঘটনা: মৃত্যু বা গুরুতর আঘাত।"},{"text":"আইনগত দায় নির্ভর করে দোষের অংশের ওপর: 100%, 75%, 50% বা 25%।"},{"text":"যে দুর্ঘটনায় কেউ আহত হয়েছে: ট্রাফিক পুলিশ (993 / 911) এবং রেড ক্রিসেন্টে (997) ফোন করুন। যে দুর্ঘটনায় শুধু ক্ষয়ক্ষতি হয়েছে: নাজম অ্যাপ ব্যবহার করুন এবং সব দিক থেকে দুর্ঘটনার ছবি তুলুন।"},{"text":"গাড়ি সরাবেন না, যদি না সেগুলো যান চলাচলে বাধা দেয় বা নিরাপত্তার জন্য হুমকি হয়, অথবা দুর্ঘটনা ছোট হয় এবং উভয় পক্ষ রাজি থাকে।"},{"text":"কোনো কারণ ছাড়া দুর্ঘটনার স্থান ছেড়ে চলে যাওয়াকে পালানো ধরা হয়। শাস্তি 2,000 রিয়াল পর্যন্ত জরিমানা এবং/অথবা 3 মাস পর্যন্ত কারাদণ্ড হতে পারে। মৃত্যু বা গুরুতর আঘাতের দুর্ঘটনায় আটক রাখা 72 ঘণ্টার বেশি হয় না।"}]},"t03":{"title":"লঙ্ঘন ও জরিমানা","blocks":[{"table":[["শ্রেণি","জরিমানা (রিয়াল)","উদাহরণ"],["1","100–150","নির্ধারিত জায়গার বাইরে পার্কিং, বৈধ বিমা না থাকা"],["2","150–300","ইন্ডিকেটর ব্যবহার না করা, সিট বেল্ট না বাঁধা, লাইসেন্স সঙ্গে না রাখা, নিরাপদ দূরত্ব কম রাখা, 20 মিটারের বেশি রিভার্স করা"],["3","300–500","রাস্তা থেকে মনোযোগ সরে যাওয়া, হঠাৎ ব্রেক করা, মেয়াদোত্তীর্ণ লাইসেন্স, শিশুর সিট ব্যবহার না করা"],["4","500–900","\"থামুন\" (STOP) সাইনে না থামা, পথ ছেড়ে দেওয়ার নিয়ম লঙ্ঘন, হাতে মোবাইল, আলো ছাড়া সুড়ঙ্গে/টানেলে গাড়ি চালানো"],["5","1000–2000","রেললাইনের ওপর থামা, সামনের নম্বর প্লেট ছাড়া গাড়ি চালানো, নিষিদ্ধ জায়গায় ওভারটেক করা, হেলমেট না পরা"],["6","3000–6000","লাল বাতি অমান্য করা, স্কুল বাস ওভারটেক করা, উল্টো দিকে গাড়ি চালানো, রেস করা"],["7","5000–10000","মদ বা মাদকের প্রভাবে গাড়ি চালানো, গাড়ির নয় এমন নম্বর প্লেট"]]},{"text":"গতিসীমা অতিক্রমের জরিমানা, সীমার চেয়ে কত বেশি তার ওপর নির্ভর করে:"},{"table":[["সীমার চেয়ে বেশি (কিমি/ঘণ্টা)","120 কিমি/ঘণ্টা পর্যন্ত রাস্তা (রিয়াল)","140 কিমি/ঘণ্টার রাস্তা (রিয়াল)"],["5–10","—","300–500"],["10–20","150–300","800–1000"],["20–30","300–500","1200–1500"],["30–40","800–1000","1500–2000"],["40–50","1200–1500","1500–2000"],["50-এর বেশি","1500–2000","1500–2000"]]},{"text":"ড্রিফটিং (তাফহীত): প্রথমবার 15 দিনের জন্য গাড়ি আটক ও 20,000 রিয়াল জরিমানা; দ্বিতীয়বার এক মাস ও 40,000; তৃতীয়বার গাড়ি বাজেয়াপ্ত ও 60,000।"},{"text":"লঙ্ঘনকারী ট্রাফিক পুলিশ না আসা পর্যন্ত নিজের গাড়ির ভেতরেই থাকবেন। সর্বনিম্ন জরিমানা 30 দিনের মধ্যে দেওয়া যায়; এরপর সর্বোচ্চ জরিমানা দিতে হয়। আবশিরের মাধ্যমে খোঁজ নিন ও পরিশোধ করুন।"}]},"t04":{"title":"লঙ্ঘনের পয়েন্ট ও লাইসেন্স স্থগিতকরণ","blocks":[{"table":[["পয়েন্ট","লঙ্ঘন"],["24","মদ বা মাদকের প্রভাবে গাড়ি চালানো"],["24","ড্রিফটিং (তাফহীত)"],["12","লাল বাতিতে না থামা"],["12","যান চলাচলের উল্টো দিকে গাড়ি চালানো"],["8","গাড়িগুলোর মাঝ দিয়ে বেপরোয়াভাবে গাড়ি চালানো"],["8","ট্রাফিক পুলিশের নির্দেশ না মানা"],["8","ব্রেক বা বাতি ছাড়া গাড়ি চালানো"],["6","\"থামুন\" (STOP) সাইনে পুরোপুরি না থামা"],["6","অগ্রাধিকার (পথ ছেড়ে দেওয়ার নিয়ম) না মানা"],["6","গতিসীমার চেয়ে 25 কিমি/ঘণ্টার বেশি গতিতে চালানো"],["6","গোলচত্বরে পথ ছেড়ে না দেওয়া"],["6","নিষিদ্ধ জায়গায় ওভারটেক করা"],["6","রেললাইনের ওপর থামা"],["4","গতিসীমার চেয়ে সর্বোচ্চ 25 কিমি/ঘণ্টা বেশি গতিতে চালানো"],["4","গাড়ির জন্য নির্ধারিত নয় এমন লেনে চালানো"],["4","যাত্রী ওঠানোর সময় স্কুল বাস ওভারটেক করা"],["4","মালামাল না ঢাকা বা না বাঁধা"],["4","আইনি প্রক্রিয়া ছাড়া গাড়ির বডি পরিবর্তন করা"],["2","সিট বেল্ট না বাঁধা"],["2","হাতে ধরে মোবাইল ফোন ব্যবহার করা"],["2","মোটরসাইকেলে হেলমেট না পরা"]]},{"text":"24 পয়েন্ট হলে লাইসেন্স স্থগিত করা হয়: এক হিজরি বছরে প্রথমবার 3 মাসের জন্য, দ্বিতীয়বার 6 মাস, তৃতীয়বার এক বছর, আর চতুর্থবার স্থায়ীভাবে বাতিল।"},{"text":"লাইসেন্স স্থগিত থাকা অবস্থায় গাড়ি চালালে বিষয়টি আদালতে পাঠানো হয়, এবং চালককে 15 দিনের পুনর্বাসন কর্মসূচিতে অংশ নিতে হতে পারে। স্থায়ীভাবে বাতিলের পর, চালক এক বছর পর নতুন লাইসেন্সের জন্য আবেদন করতে পারেন, সঙ্গে এক মাসের পুনর্বাসন কর্মসূচি এবং দুটি পরীক্ষাতেই পাস করতে হবে।"}]},"t05":{"title":"রাস্তার অংশ ও নির্দেশক সাইন","blocks":[{"text":"প্রধান সড়কে প্রবেশপথ ও বহির্গমন পথ দিয়ে ঢোকা ও বের হওয়া যায়, আর সার্ভিস রোড আশেপাশের সম্পত্তির কাজে লাগে। ট্রাফিক আইল্যান্ড (ডিভাইডার) দুই দিককে আলাদা করে, আর মার্জিং লেন দিয়ে সড়কের যানবাহনের সাথে যোগ দেওয়া যায়।"},{"text":"নির্দেশক বোর্ড: নীলের উপর সাদা অক্ষর (শহরের বাইরে, অন্য শহর ও গ্রামের দিক), সবুজ (শহরের ভেতরের রাস্তা ও এলাকা), সাদার উপর কালো অক্ষর (বিমানবন্দরের মতো গুরুত্বপূর্ণ স্থাপনা), বাদামি (খামার, রিসোর্ট, জাদুঘর ও ধর্মীয় স্থান)।"},{"text":"অস্থায়ী কাজের এলাকার সাইনগুলো একই আকারের, তবে হলুদ রঙের এবং লাল বর্ডারযুক্ত।"}]},"t06":{"title":"সড়ক ব্যবহারকারী ও আচরণ","blocks":[{"text":"আচরণের নিয়ম: নিরাপদে, সম্মানের সাথে, সাবধানে ও আইন মেনে গাড়ি চালান, এবং ট্রাফিক পুলিশের আদেশ মানুন, যদিও তা সাধারণ নিয়মের বিপরীত হয় (যেমন সবুজ বাতি জ্বলছে কিন্তু ট্রাফিক পুলিশ আপনাকে থামতে বলছে)।"},{"text":"পথচারী: একটানা সবুজ বাতিতে পার হওয়া যায়, মিটমিট করা সবুজ বাতি মানে লাল বাতি আসছে, তাই রাস্তা খালি করতে হবে, আর লাল বাতিতে পার হওয়া নিষেধ। পথচারী পারাপারে গতি কমান, থামার জন্য প্রস্তুত থাকুন এবং যে পার হওয়া শুরু করেছে তাকে বাধা দেবেন না।"},{"text":"জরুরি যানবাহন: সাথে সাথে পথ ছেড়ে দিন, এগুলোর পেছনে 50 মিটারের কম দূরত্বে গাড়ি চালাবেন না, এগুলো চলে যাওয়ার আগে পার্কিং থেকে বের হবেন না, এবং মোড় খালি করে দিন।"},{"text":"স্কুল বাস: ছাত্রছাত্রীদের ওঠা-নামার জন্য থামে, এবং থেমে থাকা অবস্থায় এগুলোকে ওভারটেক করা নিষেধ।"},{"text":"সরকারি গাড়িবহর: এগুলোকে পথ ছেড়ে দিন এবং এগুলোর মাঝখান দিয়ে যাবেন না।"},{"text":"আশেপাশের মানুষকে বয়স, মনোযোগ ও উদ্দেশ্য অনুযায়ী বুঝে নিন। শিশুরা হঠাৎ কিছু করে বসে এবং বিপদ বোঝে না, আর বয়স্করা বিভ্রান্ত হতে পারেন এবং কম শুনতে বা কম দেখতে পারেন। নিশ্চিত না হলে চোখে চোখ রেখে যোগাযোগ করুন।"}]},"t07":{"title":"চালকের দায়িত্ব ও নিষেধাজ্ঞা","blocks":[{"text":"আহত, অসুস্থ, খুব ক্লান্ত, অমনোযোগী বা উত্তেজিত অবস্থায় গাড়ি চালাবেন না, এবং মদ, মাদক বা ওষুধের প্রভাবেও না (ওষুধের লিফলেট পড়ুন)।"},{"text":"গাড়ি চালানোর আগে: জানালা, লাইট ও আয়না পরিষ্কার করুন, টায়ার, লাইট ও ব্রেক পরীক্ষা করুন, বসার অবস্থান ও আয়না ঠিক করুন এবং সিট বেল্ট বাঁধুন।"},{"text":"গাড়ি চালানোর সময়: রাস্তার পাকা অংশে, সঠিক লেনে ও অনুমোদিত গতির মধ্যে চালান, এবং মোড় নেওয়ার আগে ইন্ডিকেটর দিন।"},{"text":"নিষিদ্ধ: জরুরি অবস্থা ছাড়া হ্যাজার্ড লাইট জ্বালানো, চলার সময় ইঞ্জিন বন্ধ করা, শব্দদূষণ, গাড়িতে পর্দা ও বিজ্ঞাপন লাগানো, গাড়িকে নিজে নিজে গড়িয়ে যেতে দেওয়া, মানুষকে সিটের বাইরে বহন করা, পাবলিক রাস্তায় গাড়ি ধোয়া, ময়লা ফেলা, অনুমতি ছাড়া শোভাযাত্রায় অংশ নেওয়া।"},{"text":"গাড়ি বিকল হলে: রাস্তা খালি করুন এবং গাড়ি নিরাপদ করুন। দিনে থামার দূরত্বে একটি সতর্কতা ত্রিভুজ (ওয়ার্নিং ট্রায়াঙ্গেল) রাখুন, আর রাতে লাল বাতিও যোগ করুন।"},{"text":"গাড়ি ছেড়ে যাওয়ার সময়: ইঞ্জিন বন্ধ করুন, চাবি খুলে নিন ও গাড়ি লক করুন, এবং ফুটপাতের দিক থেকে সাবধানে দরজা খুলুন।"}]},"t08":{"title":"যাত্রী বহন ও সিট বেল্ট","blocks":[{"text":"শুধু যাত্রী বহনের জন্য তৈরি গাড়িতেই যাত্রী নেওয়া যায়; গাড়ির পেছনের মালামালের অংশে, কোনো বাইরের অংশে বা ট্রাকে যাত্রী নেওয়া নিষেধ।"},{"text":"চালক ও সব যাত্রীর জন্য সিট বেল্ট বাধ্যতামূলক, এবং চালককে যাত্রীদের মনে করিয়ে দিতে হবে। ছাড় শুধু স্বাস্থ্যগত কারণে মেডিকেল প্রমাণ ও সরকারি অনুমতিসহ, অথবা শরীরের আকারের কারণে।"},{"text":"12 বছরের কম বয়সী শিশুদের বুস্টার সিট দরকার, যাতে বেল্ট কাঁধের নিচে থাকে। 10 বছরের কম বয়সী শিশু সামনের সিটে বসতে পারবে না; তবে গাড়িতে পেছনের সিট না থাকলে উপযুক্ত চাইল্ড সিটে বসানো যাবে।"},{"text":"10 বছরের কম বয়সী শিশুদের কোনো প্রাপ্তবয়স্ক ছাড়া গাড়িতে রেখে যাওয়া লঙ্ঘন।"}]},"t09":{"title":"গাড়ি চালানো ও লেন পরিবর্তন","blocks":[{"text":"ভাঙা দাগওয়ালা দুই লেনের রাস্তায়: ডান লেন ব্যবহার করুন এবং ওভারটেক ছাড়া দাগ পার হবেন না। দুইটি একটানা দাগ পার হওয়া নিষেধ।"},{"text":"বহু লেনের রাস্তায় ধীরগতির যানবাহন একেবারে ডান দিকে চলে, যদি না বাঁয়ে মোড় নেওয়ার প্রস্তুতি নেয়।"},{"text":"একেবারে ডান দিকে থাকুন যদি আপনি ডানে মোড় নিতে চান, বা গাড়ি আপনাকে ওভারটেক করছে, বা আপনার গতি কম, বা দৃশ্যমানতা কম, বা বিপরীত দিক থেকে গাড়ি আসছে।"},{"text":"বাঁ দিক দিয়ে গাড়ি চালানো যায় ওভারটেক করতে, দুর্ঘটনা এড়াতে, অথবা নির্দেশনার কারণে ডান দিকের কিছু অংশ বন্ধ থাকলে।"},{"text":"সরু অংশ (রাস্তা সংকীর্ণ হয়ে যাওয়া জায়গা): ডানে থাকুন এবং বিপরীত দিক থেকে আসা গাড়ির জন্য পাশে জায়গা রাখুন, দরকার হলে থামুন, এবং শুধু প্রয়োজনে হর্ন বাজান।"},{"text":"লেন পরিবর্তন: আয়না → ইন্ডিকেটর → কাঁধের উপর দিয়ে দেখা (ব্লাইন্ড স্পট) → গতি ঠিক করা → মসৃণভাবে সরে যাওয়া। গতি যত বেশি, স্টিয়ারিং তত মসৃণ হতে হবে।"},{"text":"শুধু পাশের আয়নার উপর নির্ভর করলে আপনি ব্লাইন্ড স্পটের ঝুঁকিতে পড়বেন, তাই কাঁধের উপর দিয়ে তাকান।"}]},"t10":{"title":"মোড় নেওয়া, গোলচত্বর ও পেছনে চালানো","blocks":[{"text":"রাস্তায় দাগ (মার্কিং) না থাকলে: ডানে মোড় নিন একেবারে ডান দিক থেকে, ছোট বাঁকে। বামে মোড় নিন দুইমুখী রাস্তায় রাস্তার মাঝখান থেকে (মাঝের দাগের ডান পাশ থেকে), আর একমুখী রাস্তায় একেবারে বাম দিক থেকে, বড় বাঁকে। তীরচিহ্ন থাকলে সেই লেন ব্যবহার করুন যেখানে আপনার দিকের তীর আছে।"},{"text":"আগে থেকে পরিকল্পনা করুন এবং মোড়ের আগেই সঠিক লেন বেছে নিন, আগেভাগে ইন্ডিকেটর দিন এবং হঠাৎ ব্রেক না করে গতি কমান।"},{"text":"গোলচত্বর: ভেতরে থাকা যানবাহনের অগ্রাধিকার। ডানে মোড় নিতে প্রথম লেন, বামে মোড় নিতে তৃতীয় লেন ব্যবহার করুন, এবং আপনার বের হওয়ার পথের আগে ডান ইন্ডিকেটর দিন। দ্বিতীয় বের হওয়ার পথের জন্য প্রথম বের হওয়ার পথের আইল্যান্ডের কাছে ইন্ডিকেটর দিন, আর ইউ-টার্নের জন্য দ্বিতীয় বের হওয়ার পথের আইল্যান্ডের কাছে।"},{"text":"শুধু প্রয়োজন হলে এবং 20 মিটারের বেশি নয়, এমনভাবে পেছনে চালান। হাইওয়েতে পেছনে চালানো নিষেধ।"},{"text":"মোড়ে ইউ-টার্ন নেওয়া যায়, যদি কোনো সাইন তা নিষেধ না করে।"}]},"t11":{"title":"ট্রাফিক লাইট ও মোড়","blocks":[{"text":"লাল: স্টপ লাইনে বা যেখান থেকে লাইট দেখা যায় সেখানে থামুন, এবং পথচারী পারাপার পার হবেন না। সবুজ: সাবধানে চলুন এবং মোড়ে আটকে যাবেন মনে হলে তাতে ঢুকবেন না। হলুদ: সতর্ক হোন এবং বিপদ ছাড়া থামতে পারলে থামুন।"},{"text":"জ্বলা-নেভা হলুদ লাইট “পথ ছেড়ে দিন” সাইনের মতো। জ্বলা-নেভা লাল লাইট “থামুন” সাইনের মতো।"},{"text":"লাল লাইটে ডানে মোড় নেওয়া: একেবারে ডান দিক থেকে, ডান ইন্ডিকেটর দিয়ে, 2–3 সেকেন্ড থেমে, এবং 15 কিমি/ঘণ্টার কম গতিতে। ডানে মোড়ের জন্য আলাদা লেন থাকলে বা কোনো সাইন নিষেধ করলে এটা করা যাবে না।"},{"text":"“স্বয়ংক্রিয় নজরদারি” ক্যামেরার ছবি মানেই স্বয়ংক্রিয় শাস্তি নয়, কারণ প্রতিটি ছবি মানুষ হাতে যাচাই করে।"},{"text":"ট্রাফিক পুলিশের অগ্রাধিকার সবার ওপরে, তাই পুরোপুরি থামুন এবং 3 সেকেন্ড ধরে সব দিকে দেখুন।"}]},"t12":{"title":"অগ্রাধিকারের নিয়ম","blocks":[{"text":"জরুরি যানবাহনের সবসময় অগ্রাধিকার।"},{"text":"সমান মোড়: অগ্রাধিকার সেই গাড়ির যেটা মোড়ের সবচেয়ে কাছে, আর দুটো একসাথে পৌঁছালে ডান দিক থেকে আসা গাড়ির।"},{"text":"সোজা সামনে যাওয়া গাড়ির অগ্রাধিকার দিক বদলানো (বামে মোড় বা ইউ-টার্ন নেওয়া) গাড়ির চেয়ে বেশি।"},{"text":"আংশিক বন্ধ রাস্তা: অগ্রাধিকার তার, যার সামনের রাস্তা তার ডান পাশে খোলা।"},{"text":"খাড়া উতরাই/ঢাল: নিচে নামা গাড়ি ডান কিনারার কাছে থাকবে এবং ওপরে ওঠা গাড়িকে যেতে দেবে, দরকার হলে থামবে।"},{"text":"প্রধান রাস্তার অগ্রাধিকার শাখা রাস্তার চেয়ে বেশি, আর শাখা রাস্তা থেকে যে ঢোকে সে পথ ছেড়ে দেবে। প্রধান রাস্তা থেকে সার্ভিস রোডে বের হওয়া গাড়ির অগ্রাধিকার।"},{"text":"পরিস্থিতি পরিষ্কার না হলে: চোখে চোখ রেখে যোগাযোগ করুন, আর নিরাপত্তার জন্য সহায়ক হলে নিজের অগ্রাধিকার ছেড়ে দিন।"},{"text":"মোড়ে আটকে যাবেন মনে হলে তাতে ঢুকবেন না, লাইট সবুজ হলেও।"}]},"t13":{"title":"রেলক্রসিং","blocks":[{"text":"ট্রেনের অগ্রাধিকার, এবং ট্রেন কাছে এলে চালককে সাথে সাথে লাইন খালি করতে হবে। রেললাইনের ওপর থামা নিষেধ।"},{"text":"X সাইনের আগে থামুন: যখন লাইট লাল বা হলুদ, যখন গেট নড়ছে বা বন্ধ, যখন গার্ড ইশারা করে, অথবা যখন ট্রাফিকের কারণে পুরো পার হওয়া সম্ভব নয়।"},{"text":"গেট পুরোপুরি খোলা এবং লাল লাইট নিভে যাওয়া পর্যন্ত অপেক্ষা করুন, এবং নিশ্চিত হোন যে কোনো ট্রেন আসছে না।"}]},"t14":{"title":"গতি ও নিরাপদ দূরত্ব","blocks":[{"text":"ছোট যানবাহন: রাস্তায় নির্ধারিত গতিসীমা অনুযায়ী; বড় যানবাহন: শহরের ভেতরে সর্বোচ্চ 50 কিমি/ঘণ্টা। বোর্ডে লেখা গতি হলো সর্বোচ্চ সীমা, বাধ্যতামূলক গতি নয়।"},{"text":"মোড়, ক্রসিং, পিচ্ছিল রাস্তা, বাঁক, ভিড়, পথচারী, পশু, বালুঝড়, কুয়াশা ও বৃষ্টিতে গতি কমান।"},{"text":"সামনের গাড়ির পেছনে কমপক্ষে দুই সেকেন্ডের নিরাপদ দূরত্ব রাখুন। একটি স্থির জায়গা (রেফারেন্স পয়েন্ট) বেছে নিন এবং সামনের গাড়ি সেটা পার হওয়ার পর “এক হাজার এক, এক হাজার দুই” গুনুন। খারাপ আবহাওয়ায়, ভারী মাল থাকলে এবং দুই চাকার যানের পেছনে এই দূরত্ব বাড়ান।"},{"text":"সাশ্রয়ী ড্রাইভিং: সামনে দেখুন এবং আগেভাগে অ্যাক্সিলারেটর থেকে পা তুলে নিন যাতে ব্রেক ছাড়াই গতি কমে, এতে জ্বালানি কম খরচ হয় এবং ব্রেক কম ক্ষয় হয়। অকারণে থামা এড়িয়ে চলুন।"},{"text":"অকারণে হঠাৎ ব্রেক করা এবং এত ধীরে চালানো যে ট্রাফিকে বাধা হয়, দুটোই নিষেধ।"}]}};
export default table;
